def att__cuda_ok(cfg, route):
    if route[0] == 'dec4p':
        return cfg['q_len'] == 1 and cfg['window'] == 0 and (cfg['num_q_heads'] == 8 * cfg['num_kv_heads']) and (cfg['num_kv_heads'] % 2 == 0)
    return att__cuda_ok_v17(cfg, route)

def att__prologue_q_pdl(data, early):
    cfg = data['config']
    batch, hq, hkv = (cfg['batch'], cfg['num_q_heads'], cfg['num_kv_heads'])
    qkv = data['qkv']
    rope = bool(cfg['rope_theta'])
    q = torch.empty((batch, hq, 64), dtype=torch.bfloat16, device=qkv.device)
    att__prologue_p[batch,](qkv, data['positions'], data['cache_loc'], att__inv_freq(cfg['rope_theta'] if rope else 1.0, qkv.device), q, data['k_cache'], data['v_cache'], data['k_scale'], data['v_scale'], HQ=hq, HKV=hkv, ROPE=rope, QK_FACTOR=cfg['qk_scale_factor'], EPS=att_RMS_EPS, TRIGGER_EARLY=bool(early), num_warps=4)
    return q

def att__merge_pdl(data, o_part, m_part, l_part, nsplit):
    cfg = data['config']
    batch, hq, hkv = (cfg['batch'], cfg['num_q_heads'], cfg['num_kv_heads'])
    out = torch.empty((batch, 1, hq * 64), dtype=torch.bfloat16, device=data['qkv'].device)
    cb = min(att_MERGE_CB, triton.next_power_of_2(nsplit))
    att__combine_p[batch, hq](o_part, m_part, l_part, data['qkv'], data['v_scale'], out, nsplit, HQ=hq, HKV=hkv, EPS=att_RMS_EPS, CB=cb, num_warps=8 if cb > 64 else 4, launch_pdl=True)
    return out

def att__cuda_run(data, route):
    if route[0] != 'dec4p':
        return att__cuda_run_v17(data, route)
    _, cps, warps, stages, early = route
    cfg = data['config']
    batch, hq, hkv = (cfg['batch'], cfg['num_q_heads'], cfg['num_kv_heads'])
    device = data['qkv'].device
    max_pages = data['page_table'].shape[1]
    q = att__prologue_q_pdl(data, early)
    nsplit = att__nsplit_w(cfg, max_pages, cps, 32 * warps)
    o_part = torch.empty((batch * hq * nsplit, 64), dtype=torch.float32, device=device)
    m_part = torch.empty((batch * hq * nsplit,), dtype=torch.float32, device=device)
    l_part = torch.empty_like(m_part)
    getattr(att__CUDA['mod'], 'attend_dec4p')(q, data['k_cache'], data['v_cache'], data['k_scale'], data['page_table'], data['cache_seqlens'], o_part, m_part, l_part, batch, hq, hkv, max_pages, nsplit, cfg['page_size'], cfg['window'], cfg['sm_scale'], warps, stages, int(early))
    return att__merge_pdl(data, o_part, m_part, l_part, nsplit)

@triton.jit(do_not_specialize=['nsplit', 'n_rows'])
def att__combine_r(o_part_ptr, m_part_ptr, l_part_ptr, qkv_ptr, v_scale_ptr, out_ptr, nsplit, n_rows, HQ: tl.constexpr, HKV: tl.constexpr, EPS: tl.constexpr, CB: tl.constexpr, R: tl.constexpr):
    r = tl.program_id(0) * R + tl.arange(0, R)
    rok = r < n_rows
    t = r // HQ
    h = r % HQ
    d = tl.arange(0, 64)
    j = tl.arange(0, CB)
    ROW: tl.constexpr = (2 * HQ + 2 * HKV) * 64
    g = tl.load(qkv_ptr + t.to(tl.int64)[:, None] * ROW + (HQ + 2 * HKV) * 64 + h[:, None] * 64 + d[None, :], mask=rok[:, None], other=0.0).to(tl.float32)
    big = tl.full([R], -1e+30, tl.float32)
    den = tl.zeros([R], tl.float32)
    num = tl.zeros([R, 64], tl.float32)
    for s0 in range(0, nsplit, CB):
        ok = rok[:, None] & (s0 + j[None, :] < nsplit)
        idx = r.to(tl.int64)[:, None] * nsplit + s0 + j[None, :]
        m = tl.load(m_part_ptr + idx, mask=ok, other=-1e+30)
        lsum = tl.load(l_part_ptr + idx, mask=ok, other=0.0)
        o = tl.load(o_part_ptr + idx[:, :, None] * 64 + d[None, None, :], mask=ok[:, :, None], other=0.0)
        new = tl.maximum(big, tl.max(m, 1))
        scale = tl.exp2(big - new)
        w = tl.exp2(m - new[:, None])
        den = den * scale + tl.sum(w * lsum, 1)
        num = num * scale[:, None] + tl.sum(w[:, :, None] * o, 1)
        big = new
    a = num / den[:, None] * tl.load(v_scale_ptr)
    a = a * tl.rsqrt(tl.sum(a * a, 1) / 64.0 + EPS)[:, None]
    a = a / (1.0 + tl.exp(-g))
    tl.store(out_ptr + t.to(tl.int64)[:, None] * (HQ * 64) + h[:, None] * 64 + d[None, :], a.to(tl.bfloat16), mask=rok[:, None])
att__merge_v15 = att__merge

def att__merge(data, o_part, m_part, l_part, nsplit):
    if nsplit > 4:
        return att__merge_v15(data, o_part, m_part, l_part, nsplit)
    cfg = data['config']
    batch, length, hq, hkv = (cfg['batch'], cfg['q_len'], cfg['num_q_heads'], cfg['num_kv_heads'])
    out = torch.empty((batch, length, hq * 64), dtype=torch.bfloat16, device=data['qkv'].device)
    cb = triton.next_power_of_2(nsplit)
    n_rows = batch * length * hq
    att__combine_r[triton.cdiv(n_rows, 16),](o_part, m_part, l_part, data['qkv'], data['v_scale'], out, nsplit, n_rows, HQ=hq, HKV=hkv, EPS=att_RMS_EPS, CB=cb, R=16, num_warps=4)
    return out
